def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    pressure_bid = 0.0
    eric_bid = None
    tight_competitors = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        obid = 0.0
        if prev and prev.get('bid') is not None:
            obid = prev.get('bid', 0.0)
        if obid > pressure_bid:
            pressure_bid = obid
        if oid == 'Eric':
            eric_bid = obid
        if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
            tight_competitors += 1

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0.0
    if hp <= 2:
        danger += 0.7
    elif hp <= 4:
        danger += 0.4
    if no_water >= 2:
        danger += 0.8
    elif no_water == 1:
        danger += 0.35

    base = DAILY_SALARY * (0.22 + 0.38 * scarcity + danger)

    if eric_bid is not None:
        if danger >= 0.7:
            target = eric_bid + 2.5
        elif scarcity >= 0.6:
            target = eric_bid + 1.0
        else:
            target = eric_bid * 0.72
        bid = max(base, target)
    else:
        if pressure_bid > 0:
            if danger >= 0.7:
                bid = max(base, pressure_bid + 1.5)
            else:
                bid = max(base, pressure_bid * 0.7)
        else:
            bid = base

    if supply >= 22 and danger < 0.7:
        bid *= 0.72
    elif supply <= 17:
        bid *= 1.18

    if day >= 8:
        bid *= 1.12
    if tight_competitors <= 1 and danger < 0.7:
        bid *= 0.75

    min_need_bid = 0.0
    if no_water >= 2 or hp <= 2:
        min_need_bid = DAILY_SALARY * 0.92
    elif no_water == 1 or hp <= 4:
        min_need_bid = DAILY_SALARY * 0.62

    bid = max(bid, min_need_bid)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    target_bid = 40.0
    if yesterday_bids:
        target_bid = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    return min(my_status['budget'], max(target_bid * 0.95, 35.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    # Gather yesterday's max bid from opponents
    max_prev_bid = 0.0
    for opp in opponents_status.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            if prev['bid'] > max_prev_bid:
                max_prev_bid = prev['bid']

    # Urgency based on HP and no_water_days
    hp = my_status['hp']
    no_water = my_status['no_water_days']
    budget = my_status['budget']

    # If in danger of dying, bid high
    if no_water > 0 or hp <= 3:
        target_bid = max(DAILY_SALARY * 0.9, max_prev_bid + 2.0)
    else:
        target_bid = min(DAILY_SALARY * 0.6, max_prev_bid - 1.0)
        if target_bid < 0:
            target_bid = DAILY_SALARY * 0.4

    # Ensure we don't exceed budget
    return min(budget, target_bid)
